import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define custom Tanh CUDA kernel
tanh_kernel_code = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void tanh_kernel(const float* input, float* output, int num_elements) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < num_elements) {
        output[idx] = tanhf(input[idx]);
    }
}

torch::Tensor cuda_tanh(torch::Tensor x) {
    torch::Tensor output = torch::empty_like(x);

    int num_elements = x.numel();
    int threads_per_block = 256;
    int num_blocks = (num_elements + threads_per_block - 1) / threads_per_block;

    tanh_kernel<<<num_blocks, threads_per_block>>>(
        x.data_ptr<float>(),
        output.data_ptr<float>(),
        num_elements
    );

    return output;
}
"""

tanh_cpp_wrapper = "torch::Tensor cuda_tanh(torch::Tensor x);"

# Load the custom CUDA kernel
custom_tanh = load_inline(
    name='custom_tanh',
    cpp_sources=tanh_cpp_wrapper,
    cuda_sources=tanh_kernel_code,
    functions=['cuda_tanh'],
    verbose=True
)

class ModelNew(nn.Module):
    def __init__(self):
        super(ModelNew, self).__init__()

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return custom_tanh.cuda_tanh(x)
